package org.sleepwell.app;

import android.app.*;
import android.content.*;
import android.media.AudioManager;
import android.os.*;
import android.view.*;
import android.widget.*;
import java.util.*;
import java.util.concurrent.*;

/** Inline report previews own only foreground audio. Detachment or Activity pause disposes all work. */
final class ReportAudioRows extends LinearLayout implements AutoCloseable {
    private final Activity host;private final android.app.Application application;private final android.content.Context app;private final Records.Factory records;private final long id,start,end;private final ReportSounds counts;
    private final ExecutorService reader=Executors.newSingleThreadExecutor(r->new Thread(r,"SleepWell report audio"));private final Handler main=new Handler(Looper.getMainLooper());private final List<Binding> bindings=new ArrayList<>();
    private Dialog options;private ClipPlaybackPort port;private ClipReviewPlayer player;private ClipReviewPlayer.State state;private ReportAudioData.Selection selected;private boolean attached,closed,registered,checking,admissionPending;private int generation,playGeneration;private long checkedAt;
    ReportAudioRows(Activity host,long id,long start,long end,ReportSounds counts){super(host);this.host=host;app=host.getApplicationContext();application=host.getApplication();records=Records.factory;this.id=id;this.start=start;this.end=end;this.counts=counts;setOrientation(VERTICAL);add("snoring","wave",counts.userLabels>0?"Snoring events":"Snoring estimates",counts.snoring);add("speech","speech",counts.userLabels>0?"Speech events":"Speech estimates",counts.speech);add("other","wave","Other sounds",counts.other);}
    private void add(String category,String icon,String title,int count){if(count==0)return;LinearLayout block=Design.col(host),row=Design.row(host);row.setMinimumHeight(Design.dp(host,56));FrameLayout circle=new FrameLayout(host);circle.setBackground(Design.shape(host,Design.SOFT,24));Design.Icon glyph=new Design.Icon(host,icon,Design.BROWN);circle.addView(glyph,new FrameLayout.LayoutParams(Design.dp(host,21),Design.dp(host,21),Gravity.CENTER));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(Design.dp(host,36),Design.dp(host,36));cp.rightMargin=Design.dp(host,10);row.addView(circle,cp);LinearLayout copy=Design.col(host);Design.text(copy,title,13,600,Design.INK);Design.space(copy,3);Design.text(copy,count+(count==1?" event":" events"),11,400,Design.MUTED);row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));FrameLayout play=new FrameLayout(host);play.setFocusable(true);play.setContentDescription("Preview loading for "+title);play.setEnabled(false);row.addView(play,new LinearLayout.LayoutParams(Design.dp(host,48),Design.dp(host,48)));LinearLayout wave=Design.col(host);wave.setGravity(Gravity.CENTER);LinearLayout.LayoutParams wp=new LinearLayout.LayoutParams(0,Design.dp(host,40),1);wp.leftMargin=Design.dp(host,6);row.addView(wave,wp);View more=Design.iconButton(host,"more","Options for "+title,()->options(title));row.addView(more,new LinearLayout.LayoutParams(Design.dp(host,48),Design.dp(host,48)));block.addView(row);TextView notice=Design.text(block,"Loading preview…",11,400,Design.MUTED);notice.setPadding(Design.dp(host,46),0,0,Design.dp(host,4));notice.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);addView(block,new LinearLayout.LayoutParams(-1,-2));Binding binding=new Binding(category,title,play,wave,notice);bindings.add(binding);play.setOnClickListener(v->toggle(binding));}
    @Override protected void onAttachedToWindow(){super.onAttachedToWindow();if(closed||attached)return;attached=true;application.registerActivityLifecycleCallbacks(lifecycle);androidx.core.content.ContextCompat.registerReceiver(host,noisy,new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY),androidx.core.content.ContextCompat.RECEIVER_NOT_EXPORTED);registered=true;getViewTreeObserver().addOnWindowFocusChangeListener(focus);try{port=ClipPlayback.provider.create(app,records);player=new ClipReviewPlayer(port,this::state);player.visible(true);load();main.post(monitor);}catch(RuntimeException unavailable){for(Binding binding:bindings){binding.play.setVisibility(GONE);binding.notice.setText("Audio preview unavailable · reopen report");}close();}}
    private void options(String title){if(closed)return;suspend();if(options!=null)options.dismiss();options=SleepPicker.choices(host,title,new String[]{"View sound events","Audio retention settings"},-1,n->{if(closed)return;if(n==0)host.startActivity(RecordUi.intent(host,SoundEventsActivity.class).putExtra("record",id));else host.startActivity(RecordUi.intent(host,SoundLibrarySettingsActivity.class));});}
    private void load(){int ticket=++generation;reader.execute(()->{try(Store store=records.open(app)){List<ReportAudioData.Selection> selections=ReportAudioData.read(app,store,id,start,end,counts);main.post(()->{if(!live(ticket))return;for(Binding binding:bindings){ReportAudioData.Selection choice=selections.stream().filter(value->value.category.equals(binding.category)).findFirst().orElse(null);binding.selection=choice;binding.wave.removeAllViews();if(choice==null||choice.target==null){binding.notice.setText(choice==null?"Preview unavailable · reopen report":choice.issue);binding.notice.setVisibility(choice!=null&&counts.analysisOnly==counts.total&&choice.issue.equals("Analysis only · no saved recording")?GONE:VISIBLE);binding.play.setVisibility(GONE);continue;}binding.measured=new ClipWaveView(host,choice.peaks,Design.VIOLET,0xffc9b1ef);binding.wave.addView(binding.measured,new LinearLayout.LayoutParams(-1,Design.dp(host,36)));binding.play.setVisibility(VISIBLE);binding.play.setEnabled(true);binding.notice.setText("One retained event · "+clock(choice.target.duration()));update(binding);}});}catch(Exception unavailable){main.post(()->{if(live(ticket))for(Binding binding:bindings){binding.play.setVisibility(GONE);binding.notice.setText("Audio preview unavailable · reopen sound events");}});}});}
    private boolean live(int ticket){return !closed&&attached&&ticket==generation&&!host.isDestroyed();}
    private boolean occupied(){AudioManager audio=app.getSystemService(AudioManager.class);if(audio==null||audio.getMode()!=AudioManager.MODE_NORMAL)return true;SleepSoundService.Snapshot sounds=SleepSoundService.snapshot();return AlarmService.active||Prefs.flag(app,"ringing")||TrackingService.running||Prefs.flag(app,"tracking")||sounds!=null&&(sounds.state==SoundPlayback.State.PLAYING||sounds.state==SoundPlayback.State.LOADING);}
    private boolean visibleOwner(){return !closed&&attached&&isShown()&&getWindowVisibility()==VISIBLE&&host.hasWindowFocus()&&!host.isFinishing()&&!host.isDestroyed();}
    private void toggle(Binding binding){if(!visibleOwner()||admissionPending||binding.selection==null||binding.selection.target==null)return;if(occupied()){player.stop();binding.notice.setText("Pause tracking or sleep sounds before audio review.");return;}if(state!=null&&state.key.equals(binding.selection.target.key())&&(state.phase==ClipReviewPlayer.Phase.PLAYING||state.phase==ClipReviewPlayer.Phase.LOADING||state.phase==ClipReviewPlayer.Phase.READY)){player.toggle(binding.selection.target,0);return;}int ticket=generation,playTicket=++playGeneration;admissionPending=true;ReportAudioData.Selection choice=binding.selection;for(Binding other:bindings)other.play.setEnabled(false);binding.notice.setText("Checking saved interval…");reader.execute(()->{try(Store store=records.open(app)){ReportAudioData.check(app,store,choice);main.post(()->{if(!live(ticket)||playTicket!=playGeneration)return;admissionPending=false;for(Binding other:bindings)other.play.setEnabled(other.selection!=null&&other.selection.target!=null);if(!visibleOwner()||occupied()){binding.notice.setText("Playback was not started. Tap Play while this report is available.");return;}selected=choice;player.toggle(choice.target,0);});}catch(Exception changed){main.post(()->{if(live(ticket)&&playTicket==playGeneration){admissionPending=false;for(Binding other:bindings)other.play.setEnabled(other.selection!=null&&other.selection.target!=null);binding.play.setEnabled(false);binding.notice.setText("Record or audio changed · reopen sound events");player.stop();}});}});}
    private void state(ClipReviewPlayer.State value){state=value;for(Binding binding:bindings)update(binding);}
    private void update(Binding binding){if(binding.selection==null||binding.selection.target==null)return;boolean current=state!=null&&state.key.equals(binding.selection.target.key());boolean active=current&&(state.phase==ClipReviewPlayer.Phase.PLAYING||state.phase==ClipReviewPlayer.Phase.LOADING||state.phase==ClipReviewPlayer.Phase.READY);String icon=active?"pause":"play";if(!icon.equals(binding.icon)){binding.icon=icon;binding.play.removeAllViews();binding.play.setBackground(Design.touch(host,Design.SOFT,24));binding.play.addView(new Design.Icon(host,icon,Design.BROWN),new FrameLayout.LayoutParams(Design.dp(host,20),Design.dp(host,20),Gravity.CENTER));}binding.play.setContentDescription((active?"Pause ":"Play ")+binding.title+" audio preview");if(binding.measured!=null)binding.measured.progress(current?state.position/(float)binding.selection.target.duration():0);if(current)binding.notice.setText(state.phase==ClipReviewPlayer.Phase.ERROR?state.error:clock(state.position)+" / "+clock(state.duration)+" · one retained event");}
    private final Runnable monitor=new Runnable(){public void run(){if(closed)return;if(!visibleOwner()||occupied()){if(admissionPending||player!=null&&state!=null&&(state.phase==ClipReviewPlayer.Phase.PLAYING||state.phase==ClipReviewPlayer.Phase.LOADING||state.phase==ClipReviewPlayer.Phase.READY))suspend();}else if(selected!=null&&state!=null&&state.phase==ClipReviewPlayer.Phase.PLAYING&&!checking&&SystemClock.elapsedRealtime()-checkedAt>=1000){checking=true;checkedAt=SystemClock.elapsedRealtime();ReportAudioData.Selection expected=selected;int ticket=generation;reader.execute(()->{String failure="";try(Store store=records.open(app)){ReportAudioData.check(app,store,expected);}catch(Exception changed){failure="Record or audio changed · reopen sound events";}String issue=failure;main.post(()->{checking=false;if(live(ticket)&&selected==expected&&!issue.isEmpty()){player.stop();for(Binding binding:bindings)if(binding.selection==expected){binding.play.setEnabled(false);binding.notice.setText(issue);}}});});}main.postDelayed(this,100);}};
    private void suspend(){playGeneration++;if(admissionPending){admissionPending=false;for(Binding binding:bindings)binding.play.setEnabled(binding.selection!=null&&binding.selection.target!=null);}if(player!=null)player.stop();}
    private final ViewTreeObserver.OnWindowFocusChangeListener focus=focused->{if(!focused)suspend();};
    private final BroadcastReceiver noisy=new BroadcastReceiver(){public void onReceive(Context context,Intent intent){suspend();}};
    private final Application.ActivityLifecycleCallbacks lifecycle=new Application.ActivityLifecycleCallbacks(){public void onActivityPaused(Activity activity){if(activity==host)close();}public void onActivityDestroyed(Activity activity){if(activity==host)close();}public void onActivityCreated(Activity a,Bundle b){}public void onActivityStarted(Activity a){}public void onActivityResumed(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}};
    @Override protected void onDetachedFromWindow(){close();super.onDetachedFromWindow();}
    @Override public void close(){if(closed)return;closed=true;generation++;if(options!=null)options.dismiss();options=null;main.removeCallbacksAndMessages(null);if(getViewTreeObserver().isAlive())getViewTreeObserver().removeOnWindowFocusChangeListener(focus);if(registered){registered=false;try{host.unregisterReceiver(noisy);}catch(IllegalArgumentException ignored){}application.unregisterActivityLifecycleCallbacks(lifecycle);}if(player!=null)player.close();if(port!=null)port.close();reader.shutdownNow();}
    private static String clock(long value){long seconds=Math.max(0,value/1000);return seconds/60+":"+String.format(Locale.ROOT,"%02d",seconds%60);}
    private static final class Binding{final String category,title;final FrameLayout play;final LinearLayout wave;final TextView notice;ReportAudioData.Selection selection;ClipWaveView measured;String icon="";Binding(String category,String title,FrameLayout play,LinearLayout wave,TextView notice){this.category=category;this.title=title;this.play=play;this.wave=wave;this.notice=notice;}}
}
